    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Integral operators on bisimplicial diagonals", H("Integral operators on bisimplicial diagonals"), Blocks(
        Paragraph(Text("For arbitrary natural degrees s,q, an OpLetter(s,q) is a pair of simplex maps [q] → [s]. A DerivedOp(s,q) is a finitely supported integer coefficient function on these letters. Its realization on X sends X[s,s] to X[q,q]. Realization is the integer-linear extension of the two contravariant simplex actions.")),
        Paragraph(Text("For every use of a realization let C : Type u, Category.{v} C and Abelian C, with u,v independent, and let X be a bisimplicial object of C. Pure letter and coefficient operations do not depend on C. If MOne : DerivedOp(s,q) and MTwo : DerivedOp(q,r), then MTwo.comp MOne realizes as MOne.realize X followed by MTwo.realize X.")),
        Paragraph(Text("Priming prepends a new zero vertex to each simplex map and shifts every old vertex by one; its integer-linear extension raises both degrees. Boundary operators are alternating sums of paired faces. D0op, the last face, and the truncated boundary interact with priming to express the recursion of the Eilenberg–Mac Lane homotopy. A diagonal noninjective simplex map is killed by Moore retraction.")),
