        Describe.Lean(DescribeId.Create("ez-derivedoperators-e3fa491188ee"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.prime_comp"), H("prime_comp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`prime` is multiplicative** (`(β∘γ)' = β'∘γ'`), so `(MTwo ∘ MOne)' = MTwo' ∘ MOne'`. The key fact behind EM's `∂'M' = M'∂'`. Reduced to the single–single case `OpLetter.primeLetter_compLetter` by bilinearity of `comp` and additivity of `prime`.")), Paragraph(Text("In this notation, lemma prime_comp {s q r : ℕ} (MTwo : DerivedOp q r) (MOne : DerivedOp s q) : (MTwo.comp MOne).prime = MTwo.prime.comp MOne.prime."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-primehom-9f9595"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.primeHom_δ"), H("primeHom_δ"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`primeHom` shifts the face map index: `prime(δ_i) = δ_{i+1}`. The combinatorial core of `prime_faceOp`.")), Paragraph(Text("In this notation, lemma primeHom_δ {q : ℕ} (i : Fin (q + 2)) : primeHom (SimplexCategory.δ i) = SimplexCategory.δ i.succ."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-prime-faceop-0b13f6"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.prime_faceOp"), H("prime_faceOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`prime` shifts faces**: `prime(δ_i) = δ_{i+1}` (prepending the `0`-th vertex pushes the omitted vertex up by one).")), Paragraph(Text("In this notation, lemma prime_faceOp (q : ℕ) (i : Fin (q + 2)) : (faceOp q i).prime = faceOp (q + 1) i.succ."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-primehom-494f08"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.primeHom_σ"), H("primeHom_σ"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`primeHom` shifts the degeneracy map index: `prime(σ_i) = σ_{i+1}` (prepending the `0`-th vertex pushes the doubled vertex up by one). The degeneracy analog of `primeHom_δ`.")), Paragraph(Text("In this notation, lemma primeHom_σ {q : ℕ} (i : Fin (q + 1)) : primeHom (SimplexCategory.σ i) = SimplexCategory.σ i.succ."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-primeaddhom-bdb2c2"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.primeAddHom"), H("primeAddHom"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`prime` bundled as an additive hom, so it distributes over `Finset.sum` (`map_sum`) and `zsmul` (`map_zsmul`).")), Paragraph(Text("In this notation, noncomputable def primeAddHom {s q : ℕ} : DerivedOp s q →+ DerivedOp (s + 1) (q + 1)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-prime-boundaryop-9ec7ec"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.prime_boundaryOp"), H("prime_boundaryOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`∂' = prime(∂)`** (EM): the truncated boundary is the derived operator of the full boundary. Note the degree shift — `prime` of the degree-`q` boundary is the truncated boundary at degree `q+1` (this is the index offset that the literal EM transcription hides).")), Paragraph(Text("In this notation, lemma prime_boundaryOp (q : ℕ) : (boundaryOp q).prime = truncBoundaryOp (q + 1)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-facezero-comp-primehom-aa410f"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.faceZero_comp_primeHom"), H("faceZero_comp_primeHom"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The 0-th face \"eats\" the prepended vertex: `δ 0 ≫ primeHom θ = θ ≫ δ 0`. The combinatorial core of `lastFace_comp_prime`.")), Paragraph(Text("In this notation, lemma faceZero_comp_primeHom {s q : ℕ} (θ : (⦋q⦌ : SimplexCategory) ⟶ ⦋s⦌) : SimplexCategory.δ (0 : Fin (q + 2)) ≫ primeHom θ = θ ≫ SimplexCategory.δ (0 : Fin (s + 2))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-lastface-comp-prime-f1a571"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.lastFace_comp_prime"), H("lastFace_comp_prime"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`F₀ M' = M F₀`** (EM, Lemma I.3.3): dropping the bottom face commutes with priming. The one derived-operator/boundary identity that is *not* a consequence of multiplicativity, since the outer `F₀` is unprimed.")), Paragraph(Text("In this notation, lemma lastFace_comp_prime {s q : ℕ} (M : DerivedOp s q) : (lastFaceOp q).comp (M.prime) = M.comp (lastFaceOp s)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-face-zero-comp-d0-2bc7d8"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.face_zero_comp_D0"), H("face_zero_comp_D0"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The two unit faces `F_0 D₀ = F_1 D₀ = 1` (`δ_0 ≫ σ_0 = δ_1 ≫ σ_0 = 𝟙`); used to cancel the first two terms of `∂ D₀`.")), Paragraph(Text("In this notation, lemma face_zero_comp_D0 (q : ℕ) : (faceOp (q + 1) (0 : Fin (q + 3))).comp (D0op (q + 1)) = (Finsupp.single ⟨𝟙 _, 𝟙 _⟩ 1 : DerivedOp (q + 1) (q + 1))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-boundary-comp-d0-b9c854"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.boundary_comp_D0"), H("boundary_comp_D0"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Simplicial identity `∂ D₀ = D₀ ∂'` at the operator level. Writing `∂ = F₀ - ∂'`, the terms `F₀ D₀` and `F₁ D₀` both equal the identity, so the remaining faces assemble to `D₀ ∂'`.")), Paragraph(Text("In this notation, lemma boundary_comp_D0 (q : ℕ) : (boundaryOp (q + 1)).comp (D0op (q + 1)) = (D0op q).comp (truncBoundaryOp q)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-realize-diagletter-ee8af2"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.realize_diagLetter"), H("realize_diagLetter"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The realization of a **diagonal letter** `⟨θ, θ⟩` is the diagonal map `(diag X).map θ.op` (`realize_faceOp` generalized off the face case): the horizontal/vertical legs reassemble by naturality of `X.map θ.op`.")), Paragraph(Text("In this notation, lemma realize_diagLetter (X : BisimplicialObject C) {s q : ℕ} (θ : (⦋q⦌ : SimplexCategory) ⟶ ⦋s⦌) : DerivedOp.realize X (Finsupp.single (⟨θ, θ⟩ : OpLetter s q) 1) = (diag.obj X).map θ.op."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-649f5513129f"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.realize_diagLetter_comp_retractionNTwo_eq_zero_of_not_mono"), H("realize_diagLetter_comp_retractionNTwo_eq_zero_of_not_mono"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("A diagonal degeneracy `⟨θ, θ⟩` with `θ` non-monic is killed by `retractionNTwo`. Its realization is the diagonal map `(diag X).map θ.op`, and a non-monic `θ` is a simplicial degeneracy, so `degeneracy_comp_PInfty` applies after factoring `PInfty` through the Moore inclusion.")), Paragraph(Text("In this notation, lemma realize_diagLetter_comp_retractionNTwo_eq_zero_of_not_mono {s q : ℕ} (X : BisimplicialObject C) (θ : (⦋q⦌ : SimplexCategory) ⟶ ⦋s⦌) (hθ : ¬ Mono θ) : DerivedOp.realize X (Finsupp.single (⟨θ, θ⟩ : OpLetter s q) 1) ≫ (retractionNTwo X).f q = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-64f88d39487f"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.realize_comp_diagLetter_not_mono_comp_retractionNTwo"), H("realize_comp_diagLetter_not_mono_comp_retractionNTwo"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("A diagonal degeneracy on the output side kills any composite after `retractionNTwo`. If `M = ⟨θ, θ⟩ ∘ N` with `θ` non-monic, then `realize M ≫ retractionNTwo = 0`. This is the form used later, where the norm term is expressed as a diagonal degeneracy postcomposed with an arbitrary operator.")), Paragraph(Text("In this notation, lemma realize_comp_diagLetter_not_mono_comp_retractionNTwo {r s q : ℕ} (X : BisimplicialObject C) (θ : (⦋q⦌ : SimplexCategory) ⟶ ⦋s⦌) (hθ : ¬ Mono θ) (N : DerivedOp r s) : DerivedOp.realize X (DerivedOp.comp (Finsupp.single (⟨θ, θ⟩ : OpLetter s q) 1) N) ≫ (retractionNTwo X).f q = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-derivedoperators-comp-single-right"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/DerivedOperators.comp_single_right"), H("comp_single_right"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("For every s,q,r : Nat, MTwo : DerivedOp q r, lOne : OpLetter s q and c : Int, MTwo.comp (Finsupp.single lOne c) = MTwo.sum (fun lTwo cTwo => Finsupp.single (lTwo.compLetter lOne) (c*cTwo)). Composition with a single input letter is the integer-linear sum over the output operator."))), DescribeRole.Theorem))));
